input.command:
cat > config.json << 'EOF'
{
  "name": "Horror Soda Story",
  "description": "Transforms a one-sentence creative story about a can of soda into a single-sentence horror story with a terrifying twist."
}
EOF

cat > config.json << 'EOF'
{
  "name": "Silly Soda Twist",
  "description": "A humorous, silly twist added to a one-sentence story about a can of soda."
}
EOF

mkdir -p agents
cat > config.json << 'EOF'
{
  "name": "Final Soda Story",
  "description": "A cohesive three-sentence story that incorporates elements from the silly and horror soda twists."
}
EOF
cat > topology.json << 'EOF'
{
  "agents": {
    "storyteller": { "depends_on": [] }
  }
}
EOF
cat > agents/storyteller.json << 'EOF'
{
  "name": "Storyteller",
  "system_prompt": "Creative storyteller. Weave short tales with humor, horror, and satisfying conclusions.",
  "assignment": "Read the Silly Soda Twist and Horror Soda Story from previous steps. Create one final story exactly three sentences long, blending elements from both into a cohesive narrative about a can of soda.",
  "expected_output": "Final story title if any, confirmation it's three sentences, where you saved it.",
  "capabilities": []
}
EOF
